    29  struct MSBBitPumpTag;
    30
    31  // The MSB data is ordered in MSB bit order,
    32  // i.e. we push into the cache from the right and read it from the left
    33
    34  using BitPumpMSB = BitStream<MSBBitPumpTag, BitStreamCacheRightInLeftOut>;
    35
    36  template <>
    37  inline BitPumpMSB::size_type BitPumpMSB::fillCache(const uchar8* input)
    38  {
    39    static_assert(BitStreamCacheBase::MaxGetBits >= 32, "check implementation");
    40
    41    cache.push(getBE<uint32>(input), 32);
    42    return 4;
    43  }
