    33  class ByteStream : public DataBuffer
    34  {
    35  protected:
    36    size_type pos = 0; // position of stream in bytes (this is next byte to deliver)
    37
    38  public:
    39    ByteStream() = default;
    40    explicit ByteStream(const DataBuffer& buffer) : DataBuffer(buffer) {}
    41    ByteStream(const Buffer &buffer, size_type offset, size_type size_,
    42               bool inNativeByteOrder_ = true)
    43        : DataBuffer(buffer.getSubView(0, offset + size_), inNativeByteOrder_),
    44          pos(offset) {}
    45    ByteStream(const Buffer &buffer, size_type offset,
    46               bool inNativeByteOrder_ = true)
    47        : DataBuffer(buffer, inNativeByteOrder_), pos(offset) {}
    48
    49    // deprecated:
    50    ByteStream(const Buffer* f, size_type offset, size_type size_,
    51               bool inNativeByteOrder_ = true)
    52        : ByteStream(*f, offset, size_, inNativeByteOrder_) {}
    53    ByteStream(const Buffer* f, size_type offset, bool inNativeByteOrder_ = true)
    54        : ByteStream(*f, offset, inNativeByteOrder_) {}
    55
    56    // return ByteStream that starts at given offset
    57    // i.e. this->data + offset == getSubStream(offset).data
    58    ByteStream getSubStream(size_type offset, size_type size_) const {
    59      return ByteStream(getSubView(offset, size_), 0, isInNativeByteOrder());
    60    }
    61
    62    ByteStream getSubStream(size_type offset) const {
    63      return ByteStream(getSubView(offset), 0, isInNativeByteOrder());
    64    }
    65
    66    inline void check(size_type bytes) const {
    67      if (static_cast<uint64>(pos) + bytes > size)
    68        ThrowIOE("Out of bounds access in ByteStream");
    69    }
    70
    71    inline size_type getPosition() const { return pos; }
    72    inline void setPosition(size_type newPos) {
    73      pos = newPos;
    74      check(0);
    75    }
    76    inline size_type getRemainSize() const { return size-pos; }
    77    inline const uchar8* peekData(size_type count) const {
    78      return Buffer::getData(pos, count);
    79    }
    80    inline const uchar8* getData(size_type count) {
    81      const uchar8* ret = Buffer::getData(pos, count);
    82      pos += count;
    83      return ret;
    84    }
    85    inline Buffer getBuffer(size_type size_) {
    86      Buffer ret = getSubView(pos, size_);
    87      pos += size_;
    88      return ret;
    89    }
    90
    91    inline uchar8 peekByte(size_type i = 0) const {
    92      check(i+1);
    93      return data[pos+i];
    94    }
    95
    96    inline void skipBytes(size_type nbytes) {
    97      pos += nbytes;
    98      check(0);
    99    }
   100
   101    inline bool hasPatternAt(const char *pattern, size_type size_,
   102                             size_type relPos) const {
   103      if (!isValid(pos + relPos, size_))
   104        return false;
   105      return memcmp(&data[pos + relPos], pattern, size_) == 0;
   106    }
   107
   108    inline bool hasPrefix(const char *prefix, size_type size_) const {
   109      return hasPatternAt(prefix, size_, 0);
   110    }
   111
   112    inline bool skipPrefix(const char *prefix, size_type size_) {
   113      bool has_prefix = hasPrefix(prefix, size_);
   114      if (has_prefix)
   115        pos += size_;
   116      return has_prefix;
   117    }
   118
   119    inline uchar8 getByte() {
   120      check(1);
   121      return data[pos++];
   122    }
   123
   124    template<typename T> inline T peek(size_type i = 0) const {
   125      return DataBuffer::get<T>(pos, i);
   126    }
   127
   128    template<typename T> inline T get() {
   129      auto ret = peek<T>();
   130      pos += sizeof(T);
   131      return ret;
   132    }
   133
   134    inline ushort16 getU16() { return get<ushort16>(); }
   135    inline int32 getI32() { return get<int32>(); }
   136    inline uint32 getU32() { return get<uint32>(); }
   137    inline float getFloat() { return get<float>(); }
   138
   139    const char* peekString() const {
   140      if (memchr(peekData(getRemainSize()), 0, getRemainSize()) == nullptr)
   141        ThrowIOE("String is not null-terminated");
   142      return reinterpret_cast<const char*>(&data[pos]);
   143    }
   144
   145    // Increments the stream to after the next zero byte and returns the bytes in between (not a copy).
   146    // If the first byte is zero, stream is incremented one.
   147    const char* getString() {
   148      size_type start = pos;
   149      bool isNullTerminator = false;
   150      do {
   151        check(1);
   152        isNullTerminator = (data[pos] == '\0');
   153        pos++;
   154      } while (!isNullTerminator);
   155      return reinterpret_cast<const char*>(&data[start]);
   156    }
   157
   158    // recalculate the internal data/position information such that current position
   159    // i.e. getData() before == getData() after but getPosition() after == newPosition
   160    // this is only used for DNGPRIVATEDATA handling to restore the original offset
   161    // in case the private data / maker note has been moved within in the file
   162    // TODO: could add a lower bound check later if required.
   163    void rebase(const size_type newPosition, const size_type newSize) {
   164  // does that pair (position, size) make sense for this buffer? may throw
   165  #ifndef NDEBUG
   166      const uchar8* const dataRebaseCheck = Buffer::getData(newPosition, newSize);
   167  #endif
   168
   169      const uchar8* dataAtNewPosition = getData(newSize);
   170      data = dataAtNewPosition - newPosition;
   171      size = newPosition + newSize;
   172
   173  #ifndef NDEBUG
   174      // buffer sanity self-check. should not throw, unless there is a mistake
   175      const uchar8* const rebasedCheck = peekData(size);
   176
   177      // check that all the assumptions still hold, and we rebased correctly
   178      assert(getPosition() == newPosition);
   179      assert(getSize() == newSize);
   180      assert(dataRebaseCheck == rebasedCheck);
   181  #endif
   182    }
   183
   184    // special factory function to set up internal buffer with copy of passed data.
   185    // only necessary to create 'fake' TiffEntries (see e.g. RAF)
   186    static ByteStream createCopy(void* data, size_type size) {
   187      ByteStream bs;
   188      auto* new_data = alignedMalloc<uchar8, 8>(roundUp(size, 8));
   189      memcpy(new_data, data, size);
   190      bs.data = new_data;
   191      bs.size = size;
   192      bs.isOwner = true;
   193      return bs; // hint: copy elision or move will happen
   194    }
   195  };
