    33  // This allows to specify the nuber of bytes that each Buffer needs to
    34  // allocate additionally to be able to remove one runtime bounds check
    35  // in BitStream::fill. There are two sane choices:
    36  // 0 : allocate exactly as much data as required, or
    37  // set it to the value of  BitStreamCacheBase::MaxProcessBytes
    38  #define BUFFER_PADDING 0UL
    39
    40  // if the padding is >= 4, bounds checking in BitStream::fill are not compiled,
    41  // which supposedly saves about 1% on modern CPUs
    42  // WARNING: if the padding is >= 4, do *NOT* create Buffer from
    43  // passed unowning pointer and size. Or, subtract BUFFER_PADDING from size.
    44  // else bound checks will malfunction => bad things can happen !!!
    45
    46  /*************************************************************************
    47   * This is the buffer abstaction.
    48   *
    49   * It allows access to some piece of memory, typically a whole or part
    50   * of a raw file. The underlying memory may be owned by the buffer or not.
    51   * It supports move operations to properly deal with owneship transfer.
    52   * It intentionally supports only read/const access to the underlying memory.
    53   *
    54   *************************************************************************/
    55  class Buffer
    56  {
    57  public:
    58    using size_type = uint32;
    59
    60  protected:
    61    const uchar8* data = nullptr;
    62    size_type size = 0;
    63    bool isOwner = false;
    64
    65  public:
    66    // allocates the databuffer, and returns owning non-const pointer.
    67    static std::unique_ptr<uchar8, decltype(&alignedFree)> Create(size_type size);
    68
    69    // constructs an empty buffer
    70    Buffer() = default;
    71
    72    // Allocates the memory
    73    explicit Buffer(size_type size_) : Buffer(Create(size_), size_) {}
    74
    75    // creates buffer from owning unique_ptr
    76    Buffer(std::unique_ptr<uchar8, decltype(&alignedFree)> data_,
    77           size_type size_);
    78
    79    // Data already allocated
    80    explicit Buffer(const uchar8* data_, size_type size_)
    81        : data(data_), size(size_) {
    82      static_assert(BUFFER_PADDING == 0, "please do make sure that you do NOT "
    83                                         "call this function from YOUR code, and "
    84                                         "then comment-out this assert.");
    85    }
    86
    87    // creates a (non-owning) copy / view of rhs
    88    Buffer(const Buffer& rhs)
    89      : data(rhs.data), size(rhs.size) {}
    90
    91    // Move data and ownership from rhs to this
    92    Buffer(Buffer&& rhs) noexcept
    93      : data(rhs.data), size(rhs.size), isOwner(rhs.isOwner) { rhs.isOwner = false; }
    94
    95    // Frees memory if owned
    96    ~Buffer();
    97
    98    Buffer& operator=(Buffer&& rhs) noexcept;
    99    Buffer& operator=(const Buffer& rhs);
   100
   101    Buffer getSubView(size_type offset, size_type size_) const {
   102      if (!isValid(0, offset))
   103        ThrowIOE("Buffer overflow: image file may be truncated");
   104
   105      return Buffer(getData(offset, size_), size_);
   106    }
   107
   108    Buffer getSubView(size_type offset) const {
   109      size_type newSize = size - offset;
   110      return getSubView(offset, newSize);
   111    }
   112
   113    // get pointer to memory at 'offset', make sure at least 'count' bytes are accessable
   114    const uchar8* getData(size_type offset, size_type count) const {
   115      if (!isValid(offset, count))
   116        ThrowIOE("Buffer overflow: image file may be truncated");
   117
   118      return &data[offset];
   119    }
   120
   121    // convenience getter for single bytes
   122    uchar8 operator[](size_type offset) const {
   123      return *getData(offset, 1);
   124    }
   125
   126    // std begin/end iterators to allow for range loop
   127    const uchar8* begin() const {
   128      return data;
   129    }
   130    const uchar8* end() const {
   131      return data + size;
   132    }
   133
   134    // get memory of type T from byte offset 'offset + sizeof(T)*index' and swap byte order if required
   135    template<typename T> inline T get(bool inNativeByteOrder, size_type offset, size_type index = 0) const {
   136      return getByteSwapped<T>(
   137          getData(offset + index * static_cast<size_type>(sizeof(T)),
   138                  static_cast<size_type>(sizeof(T))),
   139          !inNativeByteOrder);
   140    }
   141
   142    inline size_type getSize() const {
   143      return size;
   144    }
   145
   146    inline bool isValid(size_type offset, size_type count = 1) const {
   147      return static_cast<uint64>(offset) + count <=
   148             static_cast<uint64>(size) + BUFFER_PADDING;
   149    }
   150
   151  //  Buffer* clone();
   152  //  /* For testing purposes */
   153  //  void corrupt(int errors);
   154  //  Buffer* cloneRandomSize();
   155  };
