   157  /*
   158   * DataBuffer is a simple extention to Buffer. It knows about the byte order
   159   * of its contents and can therefore provide save access to larger than
   160   * byte sized data, like int, float, etc.
   161   */
   162  class DataBuffer : public Buffer
   163  {
   164    bool inNativeByteOrder = true;
   165
   166  public:
   167    DataBuffer() = default;
   168    explicit DataBuffer(const Buffer& data_, bool inNativeByteOrder_ = true)
   169        : Buffer(data_), inNativeByteOrder(inNativeByteOrder_) {}
   170
   171    // get memory of type T from byte offset 'offset + sizeof(T)*index' and swap byte order if required
   172    template<typename T> inline T get(size_type offset, size_type index = 0) const {
   173      return Buffer::get<T>(inNativeByteOrder, offset, index);
   174    }
   175
   176    inline bool isInNativeByteOrder() const {
   177      return inNativeByteOrder;
   178    }
   179
   180    inline bool setInNativeByteOrder(bool value) {
